def generate_knowledge_base() -> Dict[str, Any]:
    return {
        "version": "1.2.0",
        "description": "Quest Coach Declarative Knowledge Base with isa hierarchies and verified nutritional and physiological data.",
        "foods": FOODS,
        "exercises": EXERCISES,
        "mindful": MINDFUL_ACTIVITIES
    }

if __name__ == "__main__":
    import os
    import json
    os.makedirs("data", exist_ok=True)
    kb = generate_knowledge_base()
    kb_path = os.path.join("data", "knowledge_base.json")
    with open(kb_path, "w", encoding="utf-8") as f:
        json.dump(kb, f, indent=2, ensure_ascii=False)
    print(f"Successfully generated {kb_path} with:")
    print(f" - {len(FOODS)} Foods")
    print(f" - {len(EXERCISES)} Exercises")
    print(f" - {len(MINDFUL_ACTIVITIES)} Mindful Activities")
